const config = {
  "previewFeatures": [],
  "clientVersion": "7.9.0",
  "engineVersion": "e922089b7d7502aff4249d5da3420f6fa55fc6ad",
  "activeProvider": "mysql",
  "inlineSchema": "generator client {\n  provider   = \"prisma-client-js\"\n  output     = \"../src/generated/prisma\"\n  engineType = \"binary\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n}\n\nenum Role {\n  ADMIN\n  SUBADMIN\n  OWNER\n  BUYER\n  AGENT\n  INVESTOR\n}\n\nenum ApprovalStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nenum ListingType {\n  SALE\n  RENT\n}\n\nenum PropertyType {\n  APARTMENT\n  PENTHOUSE\n  DUPLEX\n  VILLA\n  INDEPENDENT_HOUSE\n  PLOT\n  COMMERCIAL\n  OFFICE\n  SHOP\n  WAREHOUSE\n  PG\n}\n\nenum PropertyStatus {\n  AVAILABLE\n  SOLD\n  RENTED\n}\n\nenum PropertyCondition {\n  NEW_BOOKING\n  RESALE\n}\n\nenum ProjectStatus {\n  UPCOMING\n  UNDER_CONSTRUCTION\n  READY_TO_MOVE\n}\n\nenum PropertyImageCategory {\n  EXTERIOR\n  LIVING_ROOM\n  BEDROOM\n  KITCHEN\n  BATHROOM\n  DINING\n  BALCONY\n  FLOOR_PLAN\n  OTHER\n}\n\nmodel User {\n  id              String          @id @default(cuid())\n  name            String\n  email           String?         @unique\n  phone           String?\n  company         String?\n  slug            String?         @unique\n  about           String?         @db.Text\n  logoUrl         String?\n  licenseNumber   String?\n  address         String?         @db.Text\n  website         String?\n  metaChannelUrl  String?\n  termsAcceptedAt DateTime?\n  instagramUrl    String?\n  facebookUrl     String?\n  passwordHash    String?\n  role            Role            @default(OWNER)\n  verified        Boolean         @default(false)\n  // Live location (browser / app GPS), refreshed while the person is online. Mandatory for every role except admin.\n  liveLatitude    Float?\n  liveLongitude   Float?\n  liveLocationAt  DateTime?\n  properties      Property[]\n  subscriptions   Subscription[]\n  leadViews       LeadView[]\n  savedProperties SavedProperty[]\n  enquiries       Enquiry[]       @relation(\"EnquiryBuyer\")\n  createdAt       DateTime        @default(now())\n\n  // KYC & Customer Proof\n  referredByAgentId String?\n  secondaryPhone    String?\n  whatsappNumber    String?\n  age               Int?\n  dateOfBirth       DateTime?\n  panNumber         String?\n  panCardUrl        String?\n  aadhaarNumber     String?\n  aadhaarFrontUrl   String?\n  aadhaarBackUrl    String?\n\n  // Banking Details with Cancelled Cheque\n  bankAccountName    String?\n  bankAccountNumber  String?\n  bankIfsc           String?\n  bankName           String?\n  bankBranch         String?\n  cancelledChequeUrl String?\n\n  agentProfile         AgentProfile?\n  investorProfile      InvestorProfile?\n  propertyUnlocks      PropertyUnlock[]\n  dispatchRequests     DispatchRequest[]\n  goldListingPurchases GoldListingPurchase[]\n  visitAppointments    VisitAppointment[]\n  directVisits         DirectPropertyVisit[]         @relation(\"DirectVisitBuyer\")\n  antiBypassAgreements PlatformAntiBypassAgreement[] @relation(\"AntiBypassBuyer\")\n  agentShopUnlocks     AgentShopUnlock[]             @relation(\"BuyerAgentShopUnlocks\")\n  pushTokens           PushToken[]\n  propertyRings        PropertyRingLog[]\n  savedAgentListings   SavedAgentListing[]\n  agentListingRings    AgentListingRingLog[]\n}\n\nenum PlanRole {\n  OWNER\n  BOTH\n  AGENT\n}\n\nenum SubscriptionStatus {\n  PENDING\n  ACTIVE\n  EXPIRED\n  CANCELLED\n}\n\nmodel Plan {\n  id            String         @id @default(cuid())\n  name          String\n  role          PlanRole       @default(BOTH)\n  listingLimit  Int\n  leadLimit     Int?\n  price         Int            @default(0)\n  durationDays  Int?\n  active        Boolean        @default(true)\n  subscriptions Subscription[]\n  createdAt     DateTime       @default(now())\n  updatedAt     DateTime       @updatedAt\n}\n\nmodel Subscription {\n  id                String             @id @default(cuid())\n  userId            String\n  user              User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  planId            String\n  plan              Plan               @relation(fields: [planId], references: [id], onDelete: Cascade)\n  status            SubscriptionStatus @default(ACTIVE)\n  amount            Int?\n  startDate         DateTime           @default(now())\n  endDate           DateTime?\n  // Razorpay payment that bought this subscription; unique so one payment can\n  // never be replayed to activate/extend a plan twice.\n  razorpayPaymentId String?            @unique\n  createdAt         DateTime           @default(now())\n\n  @@index([userId])\n  @@index([planId])\n}\n\nmodel LeadView {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  enquiryId String\n  enquiry   Enquiry  @relation(fields: [enquiryId], references: [id], onDelete: Cascade)\n  createdAt DateTime @default(now())\n\n  @@unique([userId, enquiryId])\n  @@index([userId])\n}\n\nmodel Developer {\n  id              String    @id @default(cuid())\n  slug            String    @unique\n  name            String\n  logoUrl         String?\n  about           String?   @db.Text\n  website         String?\n  city            String?\n  locality        String?\n  contactEmail    String?\n  contactPhone    String?\n  verified        Boolean   @default(false)\n  metaTitle       String?\n  metaDescription String?   @db.Text\n  projects        Project[]\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n}\n\nmodel Project {\n  id              String         @id @default(cuid())\n  slug            String         @unique\n  name            String\n  description     String         @db.Text\n  status          ProjectStatus  @default(UPCOMING)\n  developerId     String\n  developer       Developer      @relation(fields: [developerId], references: [id], onDelete: Cascade)\n  city            String\n  locality        String?\n  address         String?        @db.Text\n  priceMin        Int?\n  priceMax        Int?\n  possessionDate  DateTime?\n  amenities       String?        @db.Text\n  reraNumber      String?\n  metaTitle       String?\n  metaDescription String?        @db.Text\n  units           Property[]\n  images          ProjectImage[]\n  createdAt       DateTime       @default(now())\n  updatedAt       DateTime       @updatedAt\n\n  @@index([developerId])\n}\n\nmodel ProjectImage {\n  id        String  @id @default(cuid())\n  url       String\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  order     Int     @default(0)\n}\n\nmodel Country {\n  id        String   @id @default(cuid())\n  name      String\n  slug      String   @unique\n  states    State[]\n  createdAt DateTime @default(now())\n}\n\nmodel State {\n  id        String   @id @default(cuid())\n  name      String\n  slug      String\n  countryId String\n  country   Country  @relation(fields: [countryId], references: [id], onDelete: Cascade)\n  cities    City[]\n  createdAt DateTime @default(now())\n\n  @@unique([countryId, slug])\n  @@index([countryId])\n}\n\nmodel City {\n  id              String     @id @default(cuid())\n  name            String\n  slug            String     @unique\n  stateId         String\n  state           State      @relation(fields: [stateId], references: [id], onDelete: Cascade)\n  localities      Locality[]\n  latitude        Float?\n  longitude       Float?\n  heroImage       String?\n  metaTitle       String?\n  metaDescription String?    @db.Text\n  description     String?    @db.Text\n  published       Boolean    @default(true)\n  createdAt       DateTime   @default(now())\n  updatedAt       DateTime   @updatedAt\n\n  @@index([stateId])\n}\n\nmodel Locality {\n  id              String   @id @default(cuid())\n  name            String\n  slug            String\n  cityId          String\n  city            City     @relation(fields: [cityId], references: [id], onDelete: Cascade)\n  latitude        Float?\n  longitude       Float?\n  heroImage       String?\n  metaTitle       String?\n  metaDescription String?  @db.Text\n  description     String?  @db.Text\n  published       Boolean  @default(true)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  @@unique([cityId, slug])\n  @@index([cityId])\n}\n\nmodel Property {\n  id                 String             @id @default(cuid())\n  title              String\n  slug               String             @unique\n  description        String             @db.Text\n  listingType        ListingType\n  propertyType       PropertyType\n  condition          PropertyCondition?\n  status             PropertyStatus     @default(AVAILABLE)\n  approvalStatus     ApprovalStatus     @default(PENDING)\n  expiresAt          DateTime?\n  price              Int\n  priceNegotiable    Boolean            @default(false)\n  bedrooms           Int?\n  bathrooms          Int?\n  areaSqft           Int?\n  city               String\n  locality           String?\n  address            String?            @db.Text\n  latitude           Float?\n  longitude          Float?\n  amenities          String?            @db.Text\n  nearbyAmenities    String?            @db.Text\n  brochureUrl        String?\n  youtubeUrl         String?            @db.Text\n  ownerId            String\n  owner              User               @relation(fields: [ownerId], references: [id], onDelete: Cascade)\n  projectId          String?\n  project            Project?           @relation(fields: [projectId], references: [id], onDelete: SetNull)\n  contactName        String?\n  contactPhone       String?\n  contactEmail       String?\n  featured           Boolean            @default(false)\n  metaTitle          String?\n  metaDescription    String?            @db.Text\n  commercialSubtype  String?\n  pgGender           String?\n  pgSharing          String?\n  foodIncluded       Boolean            @default(false)\n  furnishing         String?\n  floorNumber        Int?\n  totalFloors        Int?\n  carpetAreaSqft     Int?\n  superAreaSqft      Int?\n  facingDirection    String?\n  maintenanceCharges Int?\n  securityDeposit    Int?\n  possessionStatus   String?\n  bachelorFriendly   Boolean            @default(true)\n  reraNumber         String?\n  societyName        String?\n  specifications     String?            @db.Text\n  // Admin-assigned channel partner who actually handles enquiries/visits for\n  // this listing — distinct from `owner`, which for a company-held property\n  // is the admin account itself, not someone who can go show it in person.\n  // Nullable: most Property rows are dealer/owner listings with no assigned\n  // agent, where getListingAgent() falls back to the owner's own AgentProfile.\n  assignedAgentId    String?\n  assignedAgent      AgentProfile?      @relation(\"PropertyAssignedAgent\", fields: [assignedAgentId], references: [id], onDelete: SetNull)\n  images             PropertyImage[]\n  enquiries          Enquiry[]\n  savedBy            SavedProperty[]\n  ringLogs           PropertyRingLog[]\n  createdAt          DateTime           @default(now())\n  updatedAt          DateTime           @updatedAt\n\n  @@index([ownerId])\n  @@index([projectId])\n  @@index([city])\n  @@index([assignedAgentId])\n}\n\nmodel PropertyImage {\n  id         String                @id @default(cuid())\n  url        String\n  category   PropertyImageCategory @default(OTHER)\n  propertyId String\n  property   Property              @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  order      Int                   @default(0)\n}\n\nmodel Enquiry {\n  id         String     @id @default(cuid())\n  name       String\n  phone      String\n  email      String?\n  message    String?    @db.Text\n  propertyId String?\n  property   Property?  @relation(fields: [propertyId], references: [id], onDelete: SetNull)\n  buyerId    String?\n  buyer      User?      @relation(\"EnquiryBuyer\", fields: [buyerId], references: [id], onDelete: SetNull)\n  leadViews  LeadView[]\n  createdAt  DateTime   @default(now())\n\n  @@index([buyerId])\n}\n\nenum OtpChannel {\n  WHATSAPP\n  EMAIL\n}\n\nmodel OtpCode {\n  id         String     @id @default(cuid())\n  identifier String\n  channel    OtpChannel\n  code       String\n  expiresAt  DateTime\n  consumedAt DateTime?\n  createdAt  DateTime   @default(now())\n\n  @@index([identifier])\n}\n\nmodel SavedProperty {\n  id         String   @id @default(cuid())\n  userId     String\n  user       User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  propertyId String\n  property   Property @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  createdAt  DateTime @default(now())\n\n  @@unique([userId, propertyId])\n  @@index([userId])\n  @@index([propertyId])\n}\n\n// A buyer manually \"ringing\" the channel partner who listed a property\n// they've saved — distinct from the automatic QR-scan nearby-alert. Each\n// row is one ring; the 2-per-day limit (per buyer, per property) is\n// enforced by counting rows in the last 24h rather than a separate counter\n// column, so it self-expires without a cron job.\nmodel PropertyRingLog {\n  id         String   @id @default(cuid())\n  buyerId    String\n  buyer      User     @relation(fields: [buyerId], references: [id], onDelete: Cascade)\n  propertyId String\n  property   Property @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  createdAt  DateTime @default(now())\n\n  @@index([buyerId, propertyId, createdAt])\n}\n\nmodel Amenity {\n  id        String   @id @default(cuid())\n  name      String\n  slug      String   @unique\n  order     Int      @default(0)\n  createdAt DateTime @default(now())\n}\n\nmodel SiteSettings {\n  id                     String  @id @default(\"singleton\")\n  siteName               String  @default(\"BayaEstate\")\n  tagline                String? @db.Text\n  logoUrl                String?\n  favicon                String?\n  heroImage              String?\n  heroTitle              String?\n  heroSubtitle           String?\n  ctaText                String?\n  ctaLink                String?\n  whatsappNumber         String?\n  contactEmail           String?\n  contactPhone           String?\n  contactAddress         String? @db.Text\n  instagramUrl           String?\n  facebookUrl            String?\n  youtubeUrl             String?\n  linkedinUrl            String?\n  footerText             String? @db.Text\n  metaTitle              String?\n  metaDescription        String? @db.Text\n  ogImage                String?\n  googleAnalyticsId      String?\n  googleSiteVerification String?\n  tdsPercent             Int     @default(5)\n\n  // Commission & payout rates — docs/platform-requirements.md §3.11-§3.14,\n  // §3.17. All admin-editable from /admin/settings so nothing here is a\n  // hardcoded constant the client would need a code change to adjust.\n  brokeragePercent           Int @default(1) // §3.12 — 1% each side of a deal\n  profitAgentSharePercent    Int @default(10) // §3.13 — 10% to referring agent\n  profitExpenseSharePercent  Int @default(0) // 0% separate expense — unified 55% company treasury\n  profitInvestorSharePercent Int @default(35) // 35% to investor, companyShare is remainder (55%)\n  investorRegistrationFee    Int @default(20000) // §3.11 — new investor registrations only\n  investorReferralPercent    Int @default(10) // % of registrationFee credited to referring agent\n  agentReferralPercent       Int @default(10) // §3.20 — % of a referred agent's first Prime payment\n  unlockPassAmount           Int @default(100) // §3.3 — also reused by dispatch (§3.5/§6 item 2)\n  unlockAgentSplitPercent    Int @default(50)\n  goldListingAmount          Int @default(500) // §3.4\n  goldAgentSplitPercent      Int @default(50)\n  agentBasicPlanPrice        Int @default(999) // Basic Agent Plan ₹999/month\n  agentPrimePlanPrice        Int @default(1999) // Prime Agent Plan ₹1,999/month\n  agentPlanSplitPercent      Int @default(50) // PDF 1 P.1 — 50% referral split to agent wallet\n  basicListingFee            Int @default(299) // PDF 1 P.1 — Basic Property Listing ₹300 (1 Month)\n  goldListingFee             Int @default(499) // PDF 1 P.1 — Gold Property Listing ₹500 (3 Months)\n  listingSplitPercent        Int @default(50) // PDF 1 P.1 — 50% split to agent wallet\n\n  // Global Channel Partner Targets (Admin Default: 30 days, 20 properties, 10 sub-partners, 3 investors)\n  // Comma-separated CommissionType values the admin credits BY HAND (never auto-credited).\n  manualCommissionTypes String @default(\"\")\n\n  partnerTargetDays        Int @default(30)\n  partnerTargetProperties  Int @default(20)\n  partnerTargetSubPartners Int @default(10)\n  partnerTargetInvestors   Int @default(3)\n\n  updatedAt DateTime @updatedAt\n}\n\n// --- Phase 1: Agent + Investor foundation (docs/platform-requirements.md §7) ---\n\nenum AgentPlanTier {\n  BASIC\n  PRIME\n}\n\nenum ListingPlanTier {\n  BASIC\n  GOLD\n}\n\nenum AgentDocumentType {\n  RERA_CERTIFICATE\n  TRADE_LICENSE\n  GST_CERTIFICATE\n  AADHAAR_CARD_FRONT\n  AADHAAR_CARD_BACK\n  PAN_CARD\n  CANCELLED_CHEQUE\n  OTHER\n}\n\nenum InvestorFeeStatus {\n  PENDING\n  PAID\n}\n\nenum CommissionType {\n  REGISTRATION_REFERRAL\n  DEAL_PROFIT_SHARE\n  BROKERAGE\n  UNLOCK_SPLIT\n  GOLD_SPLIT\n  AGENT_REFERRAL\n  CUSTOMER_PROPERTY_UPDATE\n  REFERRAL_CUSTOMER_RENEWAL\n  COMPANY_FIVE_STAR_REWARD\n}\n\nmodel AgentProfile {\n  id                            String             @id @default(cuid())\n  userId                        String             @unique\n  user                          User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  agentCode                     String?            @unique\n  // Comma-separated CommissionType values the admin credits to THIS partner by hand.\n  manualCommissionTypes         String             @default(\"\")\n  city                          String?\n  shopName                      String?\n  shopAddress                   String?            @db.Text\n  shopLatitude                  Float?\n  shopLongitude                 Float?\n  // Most recent GPS ping from the agent app (src/app/api/agent/location) —\n  // powers the admin live map. Written via raw SQL, not prisma.update, so a\n  // ping every couple minutes doesn't trip liveVersion's refresh-everyone\n  // signal (see that route for why).\n  lastLatitude                  Float?\n  lastLongitude                 Float?\n  lastLocationAt                DateTime?\n  alternatePhone                String?\n  yearsExperience               Int?\n  staffCount                    Int?\n  reraNumber                    String?\n  gstNumber                     String?\n  status                        ApprovalStatus     @default(PENDING)\n  rejectionReason               String?            @db.Text\n  planTier                      AgentPlanTier      @default(PRIME)\n  primeStatus                   Boolean            @default(false)\n  buzzerAlerts                  Boolean            @default(true)\n  listingAlerts                 Boolean            @default(true)\n  brochureCredits               Int                @default(0)\n  brochures                     Brochure[]\n  brochureRecharges             BrochureRecharge[]\n  visibilityDeprioritized       Boolean            @default(false)\n  autoPayMandate                String?\n  autoPayActive                 Boolean            @default(false)\n  renewalAlertSentAt            DateTime?\n  walletBalance                 Int                @default(0)\n  warningCount                  Int                @default(0)\n  ratingAvg                     Float?             @default(0)\n  verifiedAt                    DateTime?\n  // 30-Day Partner Review Cycle, Target Counts & Custom Admin Overrides\n  cycleStartDate                DateTime?          @default(now())\n  cycleEndDate                  DateTime?\n  cycleDaysTarget               Int                @default(30)\n  customTargetEnabled           Boolean            @default(false)\n  cycleListingsTarget           Int                @default(5)\n  cycleDealsTarget              Int                @default(1)\n  cycleVisitsTarget             Int                @default(3)\n  cycleDirectAgentsTarget       Int                @default(10)\n  cycleCustomerPropertiesTarget Int                @default(20)\n  cycleInvestorsTarget          Int                @default(3)\n  targetStatus                  String             @default(\"YELLOW\")\n  carryForwardScore             Int                @default(0)\n  cycleCompletedCount           Int                @default(0)\n  activeDiscountCoupon          String?\n  couponExpiresAt               DateTime?\n  // §3.20 — the agent who referred this agent (self-referential, same shape\n  // as InvestorProfile.referringAgentId below). Nullable: most agents have\n  // no referrer.\n  referringAgentId              String?\n  referringAgent                AgentProfile?      @relation(\"AgentReferral\", fields: [referringAgentId], references: [id])\n  referredAgents                AgentProfile[]     @relation(\"AgentReferral\")\n  createdAt                     DateTime           @default(now())\n  updatedAt                     DateTime           @updatedAt\n\n  documents                AgentDocument[]\n  investors                InvestorProfile[]\n  commissionEntries        CommissionLedgerEntry[]\n  listings                 AgentListing[]\n  acceptedListingRequests  ListingRequest[]          @relation(\"ListingRequestAccepted\")\n  acceptedBuyerInterests   BuyerInterest[]           @relation(\"BuyerInterestAccepted\")\n  buyerInterestAcceptances BuyerInterestAcceptance[]\n  dealsAsBuyerAgent        Deal[]                    @relation(\"DealBuyerAgent\")\n  dealsAsSellerAgent       Deal[]                    @relation(\"DealSellerAgent\")\n  profitDistributions      ProfitDistribution[]\n  payoutRequests           PayoutRequest[]\n  dispatchNotifications    DispatchNotification[]\n  dispatchesAccepted       DispatchRequest[]         @relation(\"DispatchAccepted\")\n  broadcastsPosted         Broadcast[]\n  broadcastResponses       BroadcastResponse[]\n  chatMessagesSent         AgentChatMessage[]        @relation(\"ChatFrom\")\n  chatMessagesReceived     AgentChatMessage[]        @relation(\"ChatTo\")\n  visitLogs                PropertyVisitLog[]\n  ratings                  AgentRating[]\n  warnings                 AgentWarning[]\n  customerBlocks           CustomerAgentBlock[]\n  documentVaultItems       DocumentVaultItem[]\n  visitAppointments        VisitAppointment[]\n  areaAssignments          AreaAgentAssignment[]\n  assignedUnlocks          PropertyUnlock[]\n  shopUnlocks              AgentShopUnlock[]\n  assignedProperties       Property[]                @relation(\"PropertyAssignedAgent\")\n\n  @@index([status])\n  @@index([referringAgentId])\n}\n\n// \"Company har Pincode ya Area Code ko specific Agents ke IDs ke sath link\n// (map) kar deti hai... toh call random na jaakar sirf aur sirf unhi\n// chuninda area agents ko jayegi\" — Agent Registration doc, \"Company Rules\n// (Area-Wise Auto Allocation)\". Admin-managed override on top of the\n// default radius-based dispatch (src/lib/agentGeo.ts): when a dispatch's\n// pincode has any assignments here, only these agents are notified for the\n// first batch instead of the nearest-by-distance ones.\nmodel AreaAgentAssignment {\n  id        String       @id @default(cuid())\n  pincode   String\n  agentId   String\n  agent     AgentProfile @relation(fields: [agentId], references: [id], onDelete: Cascade)\n  createdAt DateTime     @default(now())\n\n  @@unique([pincode, agentId])\n  @@index([pincode])\n}\n\nmodel AgentDocument {\n  id             String            @id @default(cuid())\n  agentProfileId String\n  agentProfile   AgentProfile      @relation(fields: [agentProfileId], references: [id], onDelete: Cascade)\n  type           AgentDocumentType @default(OTHER)\n  url            String\n  createdAt      DateTime          @default(now())\n\n  @@index([agentProfileId])\n}\n\nmodel InvestorProfile {\n  id               String            @id @default(cuid())\n  userId           String            @unique\n  user             User              @relation(fields: [userId], references: [id], onDelete: Cascade)\n  investorCode     String?           @unique\n  referringAgentId String\n  referringAgent   AgentProfile      @relation(fields: [referringAgentId], references: [id])\n  registrationFee  Int               @default(20000)\n  feeStatus        InvestorFeeStatus @default(PENDING)\n  feePaymentMode   PaymentMode?\n  registeredAt     DateTime          @default(now())\n  expiresAt        DateTime?\n  totalInvested    Int               @default(0)\n  createdAt        DateTime          @default(now())\n\n  profitDistributions ProfitDistribution[]\n  ledgerEntries       InvestorLedgerEntry[]\n  documentVaultItems  DocumentVaultItem[]\n  agreements          CustomerInvestorAgreement[]\n\n  @@index([referringAgentId])\n}\n\nmodel CommissionLedgerEntry {\n  id        String         @id @default(cuid())\n  agentId   String\n  agent     AgentProfile   @relation(fields: [agentId], references: [id], onDelete: Cascade)\n  type      CommissionType\n  amount    Int\n  refId     String?\n  note      String?        @db.Text\n  createdAt DateTime       @default(now())\n\n  @@index([agentId])\n}\n\n// --- Phase 2: Listings + deduplication (docs/platform-requirements.md §7) ---\n\nmodel MasterProperty {\n  id        String   @id @default(cuid())\n  masterId  String   @unique\n  city      String\n  locality  String?\n  latitude  Float\n  longitude Float\n  createdAt DateTime @default(now())\n\n  listings           AgentListing[]\n  visitLogs          PropertyVisitLog[]\n  documentVaultItems DocumentVaultItem[]\n  visitAppointments  VisitAppointment[]\n\n  @@index([city])\n}\n\nenum ListingSource {\n  AGENT\n  CUSTOMER_GOLD\n}\n\nmodel AgentListing {\n  id                    String          @id @default(cuid())\n  masterPropertyId      String\n  masterProperty        MasterProperty  @relation(fields: [masterPropertyId], references: [id], onDelete: Cascade)\n  // Nullable: a Gold self-listing (§3.4) with no referring agent has no\n  // agent at all — \"company's number is shown... not any specific agent's.\"\n  // When present on a CUSTOMER_GOLD listing, it's the *referring* agent\n  // (who gets the 50% split), not necessarily who's actively selling it.\n  agentId               String?\n  agent                 AgentProfile?   @relation(fields: [agentId], references: [id], onDelete: Cascade)\n  source                ListingSource   @default(AGENT)\n  // AGENT listings go live immediately (unchanged Phase 2 behavior);\n  // CUSTOMER_GOLD listings default PENDING and need admin moderation\n  // (\"anti-fake-listing check\") before they're public or auto-injected.\n  approvalStatus        ApprovalStatus  @default(APPROVED)\n  slug                  String          @unique\n  title                 String\n  description           String          @db.Text\n  listingType           ListingType\n  propertyType          PropertyType\n  bedrooms              Int?\n  bathrooms             Int?\n  areaSqft              Int?\n  price                 Int\n  exactAddress          String          @db.Text\n  amenities             String?         @db.Text\n  // §3.15 — nearest Metro/Railway/Bus/Hospital/Grocery, auto-pulled at\n  // creation time, never typed manually. Distinct from `amenities` above\n  // (on-property features like gym/pool), this is *nearby places*.\n  nearbyAmenities       String?         @db.Text\n  videoUrl              String?         @db.Text\n  commercialSubtype     String?\n  pgGender              String?\n  pgSharing             String?\n  foodIncluded          Boolean         @default(false)\n  furnishing            String?\n  floorNumber           Int?\n  totalFloors           Int?\n  carpetAreaSqft        Int?\n  superAreaSqft         Int?\n  facingDirection       String?\n  maintenanceCharges    Int?\n  securityDeposit       Int?\n  bachelorFriendly      Boolean         @default(true)\n  societyName           String?\n  // PDF 1 P.1 & P.2: Basic (₹200 / 30d) vs Gold (₹500 / 90d) auto-delist\n  listingPlan           ListingPlanTier @default(BASIC)\n  listingFee            Int             @default(200)\n  listingAgentSplit     Int             @default(100)\n  listingCompanySplit   Int             @default(100)\n  listingExpiresAt      DateTime?\n  isDelisted            Boolean         @default(false)\n  delistedAt            DateTime?\n  expiryWarning7dSentAt DateTime?\n  expiryWarning2dSentAt DateTime?\n\n  // PDF 2 P.12 & P.13: 6-Month Agreement Countdown & Hot Deals Engine\n  agreementStartDate    DateTime?\n  agreementExpiryDate   DateTime?\n  hotDealAlert30dSentAt DateTime?\n  hotDealAlert15dSentAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  images               AgentListingImage[]\n  listingRequest       ListingRequest?\n  unlocks              PropertyUnlock[]\n  goldPurchase         GoldListingPurchase?\n  directVisits         DirectPropertyVisit[]\n  antiBypassAgreements PlatformAntiBypassAgreement[]\n  savedBy              SavedAgentListing[]\n  ringLogs             AgentListingRingLog[]\n\n  @@index([masterPropertyId])\n  @@index([agentId])\n  @@index([source, approvalStatus])\n  @@index([isDelisted, agreementExpiryDate])\n}\n\n// Mirrors SavedProperty, for the channel-partner marketplace listing table\n// instead of the website's own Property table — the two were never unified\n// (see /properties's merge comment), so \"save\" needs its own join table here.\nmodel SavedAgentListing {\n  id             String       @id @default(cuid())\n  userId         String\n  user           User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  agentListingId String\n  agentListing   AgentListing @relation(fields: [agentListingId], references: [id], onDelete: Cascade)\n  createdAt      DateTime     @default(now())\n\n  @@unique([userId, agentListingId])\n  @@index([userId])\n  @@index([agentListingId])\n}\n\n// Mirrors PropertyRingLog — AgentListing already has a direct agentId, so\n// ringing it doesn't need PropertyRingLog's owner->agentProfile indirection.\nmodel AgentListingRingLog {\n  id             String       @id @default(cuid())\n  buyerId        String\n  buyer          User         @relation(fields: [buyerId], references: [id], onDelete: Cascade)\n  agentListingId String\n  agentListing   AgentListing @relation(fields: [agentListingId], references: [id], onDelete: Cascade)\n  createdAt      DateTime     @default(now())\n\n  @@index([buyerId, agentListingId, createdAt])\n}\n\nmodel AgentListingImage {\n  id             String       @id @default(cuid())\n  url            String\n  agentListingId String\n  agentListing   AgentListing @relation(fields: [agentListingId], references: [id], onDelete: Cascade)\n  order          Int          @default(0)\n}\n\nmodel PropertyUnlock {\n  id              String         @id @default(cuid())\n  agentListingId  String\n  agentListing    AgentListing   @relation(fields: [agentListingId], references: [id], onDelete: Cascade)\n  buyerId         String\n  buyer           User           @relation(fields: [buyerId], references: [id], onDelete: Cascade)\n  amount          Int            @default(100)\n  agentSplit      Int            @default(50)\n  companySplit    Int            @default(50)\n  assignedAgentId String?\n  assignedAgent   AgentProfile?  @relation(fields: [assignedAgentId], references: [id])\n  buyerInterest   BuyerInterest?\n  switchedAgent   Boolean        @default(false)\n  switchedAt      DateTime?\n  switchReason    String?        @db.Text\n  expiresAt       DateTime? // PDF 1 P.2 & PDF 2 P.8: 24-Hour Exclusivity Window\n  createdAt       DateTime       @default(now())\n\n  @@unique([agentListingId, buyerId])\n  @@index([buyerId])\n  @@index([assignedAgentId])\n}\n\n// The one-time ₹500 Gold Membership payment — §3.4. One per listing\n// (that's the self-listing fee, not a per-unlock charge like PropertyUnlock\n// above). agentSplit is 0 when the listing had no referring agent code.\nmodel GoldListingPurchase {\n  id              String       @id @default(cuid())\n  agentListingId  String       @unique\n  agentListing    AgentListing @relation(fields: [agentListingId], references: [id], onDelete: Cascade)\n  buyerId         String\n  buyer           User         @relation(fields: [buyerId], references: [id], onDelete: Cascade)\n  amount          Int          @default(500)\n  agentSplit      Int          @default(0)\n  companySplit    Int          @default(500)\n  razorpayOrderId String?\n  createdAt       DateTime     @default(now())\n}\n\n// --- Phase 3: Money automation (docs/platform-requirements.md §7) ---\n\nenum PaymentMode {\n  BANK_TRANSFER\n  CHEQUE\n  CASH\n  UPI\n  NETBANKING\n}\n\nenum PayoutStatus {\n  PENDING\n  PAID\n  REJECTED\n}\n\nenum DealStatus {\n  ACTIVE\n  TOKEN_RECEIVED\n  AGREEMENT_DONE\n  REGISTRY_COMPLETED\n  CLOSED\n  CANCELLED\n}\n\n// PDF 1 Page 11 & PDF 2 Page 11:\n// 5-Stage B2B Deal Lifecycle Engine & Commission Distribution:\n// - ACTIVE (Negotiation) -> TOKEN_RECEIVED -> AGREEMENT_DONE -> REGISTRY_COMPLETED -> CLOSED\n// - 10% platform fee automatically retained by company.\n// - Remaining 90% split 50-50 between Buyer Agent (45%) & Seller Agent (45%).\nmodel Deal {\n  id                    String        @id @default(cuid())\n  dealValue             Int\n  status                DealStatus    @default(ACTIVE)\n  propertyTitle         String?\n  broadcastId           String?\n  broadcast             Broadcast?    @relation(fields: [broadcastId], references: [id])\n  buyerAgentId          String?\n  buyerAgent            AgentProfile? @relation(\"DealBuyerAgent\", fields: [buyerAgentId], references: [id])\n  sellerAgentId         String?\n  sellerAgent           AgentProfile? @relation(\"DealSellerAgent\", fields: [sellerAgentId], references: [id])\n  totalCommission       Int           @default(0)\n  platformPercent       Int           @default(10)\n  platformCommission    Int           @default(0)\n  buyerCommission       Int?\n  sellerCommission      Int?\n  tokenAmount           Int?\n  tokenDate             DateTime?\n  agreementDate         DateTime?\n  registryDate          DateTime?\n  commissionDistributed Boolean       @default(false)\n  paymentMode           PaymentMode   @default(BANK_TRANSFER)\n  note                  String?       @db.Text\n  dealDate              DateTime      @default(now())\n  createdAt             DateTime      @default(now())\n  updatedAt             DateTime      @default(now()) @updatedAt\n\n  @@index([buyerAgentId])\n  @@index([sellerAgentId])\n  @@index([status])\n  @@index([broadcastId])\n}\n\n// Investor+Company joint deal profit split — §3.13. 10% agent / 10% company\n// expense / 40% investor / 40% company, computed in one action (the \"Master\n// Commission Calculator\", §3.14).\nmodel ProfitDistribution {\n  id                String          @id @default(cuid())\n  investorProfileId String\n  investorProfile   InvestorProfile @relation(fields: [investorProfileId], references: [id], onDelete: Cascade)\n  agentId           String\n  agent             AgentProfile    @relation(fields: [agentId], references: [id])\n  totalProfit       Int\n  agentShare        Int\n  expenseShare      Int\n  investorShare     Int\n  companyShare      Int\n  paymentMode       PaymentMode\n  note              String?         @db.Text\n  distributedAt     DateTime        @default(now())\n\n  @@index([investorProfileId])\n  @@index([agentId])\n}\n\n// Investor-side ledger — Investor Portal's \"date-wise profit ledger: date,\n// customer transaction, hold duration (days), credited profit\" (§3.14).\n// Kept separate from AgentProfile's CommissionLedgerEntry: an investor's\n// profit and an agent's commission are never the same line item.\nmodel InvestorLedgerEntry {\n  id                     String          @id @default(cuid())\n  investorProfileId      String\n  investorProfile        InvestorProfile @relation(fields: [investorProfileId], references: [id], onDelete: Cascade)\n  amount                 Int\n  customerTransactionRef String?\n  holdDurationDays       Int?\n  refId                  String?\n  note                   String?         @db.Text\n  createdAt              DateTime        @default(now())\n\n  @@index([investorProfileId])\n}\n\n// Agent wallet → bank withdrawal, TDS deducted automatically before release\n// (§3.14's \"TDS & company-handling-charge deduction engine\"). Wallet balance\n// is reserved (decremented) at request time so an agent can't request more\n// than they have; rejecting a request credits it back.\nmodel PayoutRequest {\n  id          String       @id @default(cuid())\n  agentId     String\n  agent       AgentProfile @relation(fields: [agentId], references: [id], onDelete: Cascade)\n  grossAmount Int\n  tdsPercent  Int\n  tdsAmount   Int\n  netAmount   Int\n  status      PayoutStatus @default(PENDING)\n  paymentMode PaymentMode?\n  requestedAt DateTime     @default(now())\n  processedAt DateTime?\n\n  @@index([agentId])\n  @@index([status])\n}\n\n// --- Phase 4: Geolocation & Dispatch (docs/platform-requirements.md §7) ---\n\nenum DispatchStatus {\n  SEARCHING\n  MATCHED\n  EXPIRED\n  CANCELLED\n  COMPANY // BUY requirement: handled directly by company staff, never broadcast to partners\n}\n\nenum DispatchPurpose {\n  RENT\n  BUY\n  SELL\n  LETOUT\n}\n\n// Uber-style cascade dispatch — §3.5. Trigger is the same ₹100 payment as the\n// listing unlock pass (§3.3) — the client's own §3.17 monetization table has\n// only one \"₹100 unlock pass, 50/50 split\" line item, not a separate dispatch\n// fee, so this reuses that exact split rather than inventing a second charge.\nmodel DispatchRequest {\n  id              String         @id @default(cuid())\n  buyerId         String\n  buyer           User           @relation(fields: [buyerId], references: [id], onDelete: Cascade)\n  latitude        Float\n  longitude       Float\n  amount          Int            @default(100)\n  agentSplit      Int            @default(50)\n  companySplit    Int            @default(50)\n  paymentMode     PaymentMode?\n  razorpayOrderId String?\n  status          DispatchStatus @default(SEARCHING)\n  currentRadiusKm Int            @default(1)\n  currentBatch    Int            @default(1)\n  batchStartedAt  DateTime       @default(now())\n\n  // What the customer asked for (dropdown form). BUY goes to the company desk.\n  purpose          DispatchPurpose @default(RENT)\n  selectedRadiusKm Int             @default(5)\n  societyName      String?\n  bhk              Int?\n  budgetMin        Int?\n  budgetMax        Int?\n  budgetLabel      String?\n  highPriority     Boolean         @default(false)\n  // Company BUY desk\n  staffId          String?\n  staffNote        String?         @db.Text\n  contactedAt      DateTime?\n\n  acceptedByAgentId String?\n  acceptedAgent     AgentProfile? @relation(\"DispatchAccepted\", fields: [acceptedByAgentId], references: [id])\n  acceptedAt        DateTime?\n  createdAt         DateTime      @default(now())\n\n  notifications DispatchNotification[]\n\n  @@index([buyerId])\n  @@index([status])\n}\n\n// One row per (dispatch, agent) the cascade has ever notified — also the\n// idempotency guard against re-notifying the same agent in a later batch.\nmodel DispatchNotification {\n  id                String          @id @default(cuid())\n  dispatchRequestId String\n  dispatchRequest   DispatchRequest @relation(fields: [dispatchRequestId], references: [id], onDelete: Cascade)\n  agentId           String\n  agent             AgentProfile    @relation(fields: [agentId], references: [id], onDelete: Cascade)\n  batch             Int\n  createdAt         DateTime        @default(now())\n\n  @@unique([dispatchRequestId, agentId])\n  @@index([agentId])\n}\n\nenum BroadcastStatus {\n  OPEN\n  CLOSED\n}\n\n// Agent-facing inventory-sourcing categories — Rent/Buy/Sell/Letout, all\n// four, unlike the customer-facing Buy/Rent-only rule (§3.3 addendum). This\n// enum is intentionally separate from the public-facing ListingType.\nenum BroadcastTxnType {\n  RENT\n  BUY\n  SELL\n  LETOUT\n}\n\n// B2B agent-to-agent broadcast — §3.6. \"Radius (1/3/5km) → Society →\n// Flat size → Transaction type → Budget range\", pure dropdowns, no free text.\nmodel Broadcast {\n  id        String           @id @default(cuid())\n  agentId   String\n  agent     AgentProfile     @relation(fields: [agentId], references: [id], onDelete: Cascade)\n  latitude  Float\n  longitude Float\n  radiusKm  Int\n  society   String?\n  flatSize  String\n  txnType   BroadcastTxnType\n  budgetMin Int\n  budgetMax Int\n  status    BroadcastStatus  @default(OPEN)\n  createdAt DateTime         @default(now())\n\n  responses BroadcastResponse[]\n  messages  AgentChatMessage[]\n  deals     Deal[]\n\n  @@index([agentId])\n  @@index([status])\n}\n\n// \"I Have This Property\" click — opens the Agent Code ↔ Agent Code chat.\nmodel BroadcastResponse {\n  id          String       @id @default(cuid())\n  broadcastId String\n  broadcast   Broadcast    @relation(fields: [broadcastId], references: [id], onDelete: Cascade)\n  agentId     String\n  agent       AgentProfile @relation(fields: [agentId], references: [id], onDelete: Cascade)\n  createdAt   DateTime     @default(now())\n\n  @@unique([broadcastId, agentId])\n  @@index([agentId])\n}\n\n// Encrypted-in-transit (HTTPS + Socket.io over TLS in production) Agent\n// Code ↔ Agent Code chat, always scoped to the broadcast that started it —\n// §3.6 doesn't describe a general-purpose DM, only a per-requirement thread.\nmodel AgentChatMessage {\n  id          String       @id @default(cuid())\n  broadcastId String\n  broadcast   Broadcast    @relation(fields: [broadcastId], references: [id], onDelete: Cascade)\n  fromAgentId String\n  fromAgent   AgentProfile @relation(\"ChatFrom\", fields: [fromAgentId], references: [id], onDelete: Cascade)\n  toAgentId   String\n  toAgent     AgentProfile @relation(\"ChatTo\", fields: [toAgentId], references: [id], onDelete: Cascade)\n  message     String       @db.Text\n  readAt      DateTime?\n  createdAt   DateTime     @default(now())\n\n  @@index([broadcastId])\n  @@index([toAgentId])\n}\n\n// --- Phase 5: Trust & Retention (docs/platform-requirements.md §7) ---\n\n// Immutable audit table — §3.8's anti-poaching/conflict protection. Rows are\n// never edited or deleted; a conflict is a *new* row with isPrimaryOwner\n// false, not a correction of the original.\nmodel PropertyVisitLog {\n  id                  String         @id @default(cuid())\n  customerPhone       String\n  customerName        String?\n  masterPropertyId    String\n  masterProperty      MasterProperty @relation(fields: [masterPropertyId], references: [id], onDelete: Cascade)\n  agentId             String\n  agent               AgentProfile   @relation(fields: [agentId], references: [id], onDelete: Cascade)\n  otpVerified         Boolean        @default(true)\n  isPrimaryOwner      Boolean        @default(true)\n  conflictWithAgentId String?\n  visitedAt           DateTime       @default(now())\n\n  @@index([customerPhone, masterPropertyId])\n  @@index([agentId])\n}\n\n// 5-star rating + written review after a visit/deal — §3.9.\nmodel AgentRating {\n  id               String       @id @default(cuid())\n  agentId          String\n  agent            AgentProfile @relation(fields: [agentId], references: [id], onDelete: Cascade)\n  customerPhone    String\n  masterPropertyId String?\n  stars            Int\n  review           String?      @db.Text\n  createdAt        DateTime     @default(now())\n\n  @@index([agentId])\n}\n\n// 3-strike rule — §3.9: 3 verified complaints against one Agent Code →\n// visible ranking drop + warning to both agent and customer.\nmodel AgentWarning {\n  id        String       @id @default(cuid())\n  agentId   String\n  agent     AgentProfile @relation(fields: [agentId], references: [id], onDelete: Cascade)\n  reason    String       @db.Text\n  createdAt DateTime     @default(now())\n\n  @@index([agentId])\n}\n\n// A formal complaint permanently blocks that agent from ever being\n// re-shown to this customer again — §3.9: \"must never be re-shown to that\n// same customer again for a new lead in the same area.\"\nmodel CustomerAgentBlock {\n  id            String       @id @default(cuid())\n  customerPhone String\n  agentId       String\n  agent         AgentProfile @relation(fields: [agentId], references: [id], onDelete: Cascade)\n  reason        String       @db.Text\n  createdAt     DateTime     @default(now())\n\n  @@unique([customerPhone, agentId])\n  @@index([customerPhone])\n}\n\n// Abuse-guardrail ledger — §3.9: max 3 switch/buzzer actions per customer\n// per day, 1-2hr cooldown between uses, mandatory reason before the switch\n// button is even clickable.\nmodel AgentSwitchLog {\n  id            String   @id @default(cuid())\n  customerPhone String\n  fromAgentId   String\n  toAgentId     String?\n  reason        String   @db.Text\n  isComplaint   Boolean  @default(false)\n  createdAt     DateTime @default(now())\n\n  @@index([customerPhone])\n}\n\nenum DocumentVaultType {\n  REGISTRY\n  SALE_DEED\n  AGREEMENT_TO_SELL\n  ENCUMBRANCE_CERTIFICATE\n  LAYOUT_PLAN\n  PAYMENT_RECEIPT\n  SIGNED_AGREEMENT\n  CUSTOMER_BANK_LOAN_PAPERS\n  COMPANY_INVESTOR_AGREEMENT\n  CANCELLED_CHEQUE\n  AADHAAR_CARD\n  PAN_CARD\n  OTHER\n}\n\n// §3.10 — \"Access is code-scoped: visible only inside the relevant Agent\n// Code / Investor Code dashboards.\" A vault item always belongs to exactly\n// one of agentId/investorId (whichever dashboard it should surface in),\n// optionally also tagged to a Master Property.\nmodel DocumentVaultItem {\n  id               String            @id @default(cuid())\n  masterPropertyId String?\n  masterProperty   MasterProperty?   @relation(fields: [masterPropertyId], references: [id], onDelete: Cascade)\n  dealId           String?\n  agentId          String?\n  agent            AgentProfile?     @relation(fields: [agentId], references: [id], onDelete: Cascade)\n  investorId       String?\n  investor         InvestorProfile?  @relation(fields: [investorId], references: [id], onDelete: Cascade)\n  type             DocumentVaultType @default(OTHER)\n  title            String\n  url              String\n  uploadedByUserId String\n  createdAt        DateTime          @default(now())\n\n  @@index([masterPropertyId])\n  @@index([agentId])\n  @@index([investorId])\n}\n\n// Customer↔Investor agreement record — §3.10's named sub-requirement:\n// \"customer name/contact, agreement date, lock-in period, flat/unit number,\n// terms, signed copy upload.\"\nmodel CustomerInvestorAgreement {\n  id                 String          @id @default(cuid())\n  investorId         String\n  investor           InvestorProfile @relation(fields: [investorId], references: [id], onDelete: Cascade)\n  customerName       String\n  customerPhone      String\n  agreementDate      DateTime\n  lockInPeriodMonths Int?\n  flatUnitNumber     String?\n  terms              String?         @db.Text\n  signedCopyUrl      String\n  // \"Investor ne customer ki property buy/book karne ke liye kitna payment\n  // diya aur uska payment mode kya tha\" — the Investor→Customer leg, tracked\n  // separately from the Investor→Company registration-fee leg\n  // (InvestorProfile.feePaymentMode).\n  paymentAmount      Int?\n  paymentMode        PaymentMode?\n  createdAt          DateTime        @default(now())\n\n  @@index([investorId])\n}\n\n// --- §3.7 Calendar / Meeting Board / CRM (unassigned to a numbered phase in\n// §7's roadmap — built as the last remaining spec'd module) ---\n\nenum AppointmentStatus {\n  SCHEDULED\n  COMPLETED\n  NO_SHOW\n  CANCELLED\n}\n\n// \"Shared calendar slot booked between agent & customer for a site visit;\n// both get reminders... full audit trail: visit date, inquiry date,\n// follow-up due date\" — §3.7. `bookingCode` is the customer's \"existing\n// unique booking code\" the no-show escalation flow reuses.\nmodel VisitAppointment {\n  id               String            @id @default(cuid())\n  bookingCode      String            @unique\n  buyerId          String\n  buyer            User              @relation(fields: [buyerId], references: [id], onDelete: Cascade)\n  agentId          String\n  agent            AgentProfile      @relation(fields: [agentId], references: [id], onDelete: Cascade)\n  masterPropertyId String?\n  masterProperty   MasterProperty?   @relation(fields: [masterPropertyId], references: [id], onDelete: SetNull)\n  scheduledAt      DateTime\n  status           AppointmentStatus @default(SCHEDULED)\n  followUpDueAt    DateTime?\n  reminderSentAt   DateTime?\n  createdAt        DateTime          @default(now())\n\n  @@index([buyerId])\n  @@index([agentId])\n  @@index([status])\n}\n\n// PDF 2 Page 10:\n// Direct Customer-Owner Property Visit with OTP Verification & GPS proof\nmodel DirectPropertyVisit {\n  id               String       @id @default(cuid())\n  agentListingId   String\n  agentListing     AgentListing @relation(fields: [agentListingId], references: [id], onDelete: Cascade)\n  buyerId          String\n  buyer            User         @relation(\"DirectVisitBuyer\", fields: [buyerId], references: [id], onDelete: Cascade)\n  ownerPhone       String?\n  otp              String?\n  otpVerified      Boolean      @default(false)\n  otpVerifiedAt    DateTime?\n  latitude         Float?\n  longitude        Float?\n  locationAccuracy Float?\n  notes            String?      @db.Text\n  createdAt        DateTime     @default(now())\n\n  antiBypassAgreements PlatformAntiBypassAgreement[]\n\n  @@index([agentListingId])\n  @@index([buyerId])\n}\n\n// PDF 2 Page 11:\n// Platform Anti-Bypass Legal Agreement Deed\n// Automatically generated upon verified physical site visit to prevent buyer/seller from bypassing platform fee\nmodel PlatformAntiBypassAgreement {\n  id                String               @id @default(cuid())\n  directVisitId     String?\n  directVisit       DirectPropertyVisit? @relation(fields: [directVisitId], references: [id], onDelete: SetNull)\n  agentListingId    String\n  agentListing      AgentListing         @relation(fields: [agentListingId], references: [id], onDelete: Cascade)\n  buyerId           String\n  buyer             User                 @relation(\"AntiBypassBuyer\", fields: [buyerId], references: [id], onDelete: Cascade)\n  sellerPhone       String\n  sellerName        String?\n  buyerName         String?\n  buyerPhone        String?\n  propertyAddress   String               @db.Text\n  legalTermsSummary String               @db.Text\n  serviceFeePercent Float                @default(1.0)\n  buyerSigned       Boolean              @default(false)\n  buyerSignedAt     DateTime?\n  sellerSigned      Boolean              @default(false)\n  sellerSignedAt    DateTime?\n  status            String               @default(\"ACTIVE\")\n  createdAt         DateTime             @default(now())\n  updatedAt         DateTime             @default(now()) @updatedAt\n\n  @@index([agentListingId])\n  @@index([buyerId])\n}\n\n// Customer QR scan unlock fee (₹50) to access an Agent's verified shop and full properties\nmodel AgentShopUnlock {\n  id                String       @id @default(cuid())\n  agentId           String\n  agent             AgentProfile @relation(fields: [agentId], references: [id], onDelete: Cascade)\n  buyerId           String?\n  buyer             User?        @relation(\"BuyerAgentShopUnlocks\", fields: [buyerId], references: [id], onDelete: Cascade)\n  customerPhone     String?\n  amount            Int          @default(50)\n  razorpayOrderId   String?\n  razorpayPaymentId String?\n  createdAt         DateTime     @default(now())\n\n  @@index([buyerId])\n  @@index([agentId])\n  @@index([customerPhone])\n}\n\n// A mobile FCM device token for one logged-in user (a channel partner's\n// phone, so far) — used to ring them when a buyer scans a nearby QR\n// (lib/push.ts). A user can hold more than one (reinstall, second device).\nmodel PushToken {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  token     String   @unique\n  platform  String // \"ANDROID\" for now\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n}\n\n// --- Assisted owner listing -------------------------------------------------\n// Owners cannot list on their own. They pay for a plan, the nearest channel\n// partners get a buzzer, the first to accept calls the owner and sends a\n// one-time link; the owner fills the property details there and the listing\n// is created under that partner's ID (50-50 split of the plan fee).\nenum ListingRequestStatus {\n  PENDING_PAYMENT\n  DETAILS_PENDING // paid; the owner is filling in the property details (then the buzzer rings)\n  SEARCHING\n  ACCEPTED\n  LINK_SENT\n  SUBMITTED\n  CANCELLED\n  ADMIN_DESK // a SELL request: handled by the admin team only, never shown to any partner\n}\n\nenum ListingPurpose {\n  RENT\n  SELL\n}\n\nmodel ListingRequest {\n  id                  String               @id @default(cuid())\n  userId              String?\n  ownerName           String\n  ownerPhone          String\n  ownerEmail          String?\n  city                String\n  locality            String?\n  latitude            Float?\n  longitude           Float?\n  plan                ListingPlanTier      @default(BASIC)\n  purpose             ListingPurpose       @default(RENT)\n  amount              Int\n  agentSplit          Int\n  companySplit        Int\n  referredByAgentCode String?\n  razorpayOrderId     String?\n  status              ListingRequestStatus @default(PENDING_PAYMENT)\n  // statusToken lets the owner watch progress; formToken is the link the agent sends.\n  statusToken         String               @unique\n  formToken           String               @unique\n  alertedAgentIds     String?              @db.Text\n  buzzCount           Int                  @default(0)\n  lastBuzzAt          DateTime?\n  acceptedByAgentId   String?\n  acceptedAgent       AgentProfile?        @relation(\"ListingRequestAccepted\", fields: [acceptedByAgentId], references: [id], onDelete: SetNull)\n  acceptedAt          DateTime?\n  linkSentAt          DateTime?\n  paidAt              DateTime?\n  agentListingId      String?              @unique\n  agentListing        AgentListing?        @relation(fields: [agentListingId], references: [id], onDelete: SetNull)\n  adminNote           String?              @db.Text\n  // Owner-submitted property details (JSON). The AgentListing is only created after the partner verifies on site with the owner's OTP.\n  detailsJson         String?              @db.LongText\n  detailsAt           DateTime?\n  // Buzzer cycle: 5 km -> 10 km -> 15 km. Restarts (skipping skippedAgentIds) if nobody verifies within 48 hours.\n  buzzRadiusKm        Int                  @default(0)\n  searchStartedAt     DateTime?\n  skippedAgentIds     String?              @db.Text\n  createdAt           DateTime             @default(now())\n  updatedAt           DateTime             @updatedAt\n\n  @@index([status])\n  @@index([acceptedByAgentId])\n}\n\n// --- Buyer interest (the buzzer after a ₹100 unlock) -------------------------\n// When a buyer pays to unlock a listing, the listing's partner is buzzed at once.\n// 10 seconds later every partner within 5 km is buzzed (\"a buyer wants a property\n// like this\"), then 15 km, then everyone. The first partner to accept gets the\n// buyer's number, and the buyer can then see ALL of that partner's listings via\n// the partner's shop link.\nenum BuyerInterestStatus {\n  OPEN\n  ACCEPTED\n  CLOSED\n}\n\nmodel BuyerInterest {\n  id                String                    @id @default(cuid())\n  unlockId          String                    @unique\n  unlock            PropertyUnlock            @relation(fields: [unlockId], references: [id], onDelete: Cascade)\n  buyerId           String\n  agentListingId    String\n  primaryAgentId    String?\n  latitude          Float?\n  longitude         Float?\n  listingTitle      String\n  listingCity       String?\n  listingLocality   String?\n  listingType       String\n  propertyType      String\n  listingPrice      Int\n  bedrooms          Int?\n  status            BuyerInterestStatus       @default(OPEN)\n  acceptedByAgentId String?\n  acceptedAgent     AgentProfile?             @relation(\"BuyerInterestAccepted\", fields: [acceptedByAgentId], references: [id], onDelete: SetNull)\n  acceptedAt        DateTime?\n  acceptances       BuyerInterestAcceptance[]\n  notifiedAgentIds  String?                   @db.Text\n  buzzCount         Int                       @default(0)\n  adminNote         String?                   @db.Text\n  createdAt         DateTime                  @default(now())\n  updatedAt         DateTime                  @updatedAt\n\n  @@index([status])\n  @@index([buyerId])\n  @@index([acceptedByAgentId])\n}\n\n// Several partners can take the same buyer (up to MAX_ACCEPTORS): each gets the buyer's\n// number and the buyer can open each of their shops.\nmodel BuyerInterestAcceptance {\n  id         String        @id @default(cuid())\n  interestId String\n  interest   BuyerInterest @relation(fields: [interestId], references: [id], onDelete: Cascade)\n  agentId    String\n  agent      AgentProfile  @relation(fields: [agentId], references: [id], onDelete: Cascade)\n  acceptedAt DateTime      @default(now())\n\n  @@unique([interestId, agentId])\n  @@index([agentId])\n}\n\nenum SupportCategory {\n  COMMISSION_CONFLICT\n  CUSTOMER_COMPLAINT\n  WEBSITE_FEEDBACK\n}\n\nenum SupportStatus {\n  OPEN\n  IN_REVIEW\n  RESOLVED\n}\n\n// Support & dispute desk — commission conflicts / complaints are audited and\n// resolved within a 2 hour SLA (dueAt).\nmodel SupportTicket {\n  id         String          @id @default(cuid())\n  userId     String\n  role       String\n  category   SupportCategory\n  subject    String\n  message    String          @db.Text\n  status     SupportStatus   @default(OPEN)\n  resolution String?         @db.Text\n  dueAt      DateTime\n  resolvedAt DateTime?\n  createdAt  DateTime        @default(now())\n\n  @@index([status, dueAt])\n  @@index([userId])\n}\n\n// Agent-made property brochures. Each pack of credits (default Rs 100 = 10\n// brochures) is bought via BrochureRecharge; one credit is spent per Brochure.\n// `data` is a JSON snapshot so re-opening a brochure is free and never changes.\nmodel Brochure {\n  id         String       @id @default(cuid())\n  agentId    String\n  agent      AgentProfile @relation(fields: [agentId], references: [id], onDelete: Cascade)\n  sourceType String\n  sourceRef  String\n  title      String\n  data       String       @db.LongText\n  createdAt  DateTime     @default(now())\n\n  @@index([agentId, createdAt])\n}\n\nmodel BrochureRecharge {\n  id                String       @id @default(cuid())\n  agentId           String\n  agent             AgentProfile @relation(fields: [agentId], references: [id], onDelete: Cascade)\n  amount            Int\n  credits           Int\n  source            String       @default(\"PAID\")\n  razorpayOrderId   String?\n  razorpayPaymentId String?\n  note              String?\n  createdAt         DateTime     @default(now())\n\n  @@index([agentId, createdAt])\n}\n\n// --- Office visits & reception desk ---\n// One row per reception check-in (or manual \"No\" mark) of a partner at the office.\nmodel AgentOfficeVisit {\n  id           String   @id @default(cuid())\n  agentId      String\n  visited      Boolean  @default(true)\n  visitedAt    DateTime @default(now())\n  notes        String?  @db.Text\n  markedById   String?\n  markedByName String?\n  createdAt    DateTime @default(now())\n\n  visitors OfficeVisitor[]\n\n  @@index([agentId, visitedAt])\n}\n\n// People who came to the office with the partner (client / investor / friend / relative).\nmodel OfficeVisitor {\n  id        String           @id @default(cuid())\n  visitId   String\n  visit     AgentOfficeVisit @relation(fields: [visitId], references: [id], onDelete: Cascade)\n  agentId   String\n  name      String\n  mobile    String\n  relation  String           @default(\"CLIENT\") // CLIENT | INVESTOR | FRIEND | RELATIVE\n  interest  String           @default(\"GENERAL\") // BUY | INVESTMENT | GENERAL\n  visitedAt DateTime         @default(now())\n\n  @@index([visitId])\n  @@index([agentId])\n  @@index([mobile])\n}\n\n// --- Property cart ---\nmodel CartItem {\n  id             String   @id @default(cuid())\n  userId         String\n  propertyId     String?\n  agentListingId String?\n  createdAt      DateTime @default(now())\n\n  @@unique([userId, propertyId])\n  @@unique([userId, agentListingId])\n  @@index([userId])\n}\n\n// A shared / sent-to-agent snapshot of a cart. `token` is the public share link.\nmodel CartShare {\n  id        String    @id @default(cuid())\n  token     String    @unique\n  userId    String\n  agentId   String?\n  itemsJson String    @db.LongText\n  note      String?   @db.Text\n  sentAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([userId])\n  @@index([agentId])\n}\n\n// --- Requirement watch-list ---\n// Saved when no property exists within radius; triggered when a matching listing appears.\nmodel WatchRequirement {\n  id               String    @id @default(cuid())\n  buyerId          String\n  purpose          String    @default(\"RENT\") // RENT | BUY\n  bhk              Int?\n  budgetMin        Int?\n  budgetMax        Int?\n  societyName      String?\n  latitude         Float\n  longitude        Float\n  radiusKm         Int       @default(5)\n  status           String    @default(\"ACTIVE\") // ACTIVE | MATCHED | CANCELLED\n  matchedListingId String?\n  matchedAgentId   String?\n  matchedAt        DateTime?\n  createdAt        DateTime  @default(now())\n\n  @@index([buyerId])\n  @@index([status])\n}\n"
}

